/bin/bash -lc "node - <<'NODE'
const fs = require('fs');
const { execFileSync } = require('child_process');
const pkg = JSON.parse(fs.readFileSync('package.json','utf8'));
const deps = [];
for (const section of ['dependencies','devDependencies']) for (const [name, range] of Object.entries(pkg[section]||{})) deps.push({section,name,range});
for (const dep of deps) {
  try {
    const latest = execFileSync('npm', ['view', dep.name, 'version'], {encoding:'utf8', stdio:['ignore','pipe','pipe']}).trim();
    console.log([dep.section, dep.name, dep.range, latest].join('\\t'));
  } catch (err) {
    console.log([dep.section, dep.name, dep.range, 'ERROR:' + err.message.replace(/\\s+/g,' ')].join('\\t'));
  }
}
NODE"

